CustomField.formula:
IF(
    IsPersonAccount,
    /* PERSON ACCOUNT */
    AND(
        NOT(ISBLANK(FirstName)),
        NOT(ISBLANK(LastName)),
        TRIM(FirstName) = UPPER(TRIM(FirstName)),
        TRIM(LastName) = UPPER(TRIM(LastName))
    ),
    /* ACCOUNT NORMAL */
    AND(
        NOT(ISBLANK(Name)),
        TRIM(Name) = UPPER(TRIM(Name))
    )
)
